package android.content;
import android.net.Uri; import java.util.HashMap; import java.util.Map;
public class Intent { public static final String ACTION_SEND="android.intent.action.SEND", ACTION_MAIN="android.intent.action.MAIN", EXTRA_TEXT="android.intent.extra.TEXT"; private String action; private Uri data; private final Map<String,Object> extras=new HashMap<>(); private Class<?> target; public Intent(){} public Intent(Context c,Class<?> t){target=t;} public Intent(Intent o){action=o.action;data=o.data;extras.putAll(o.extras);target=o.target;} public Intent setAction(String a){action=a;return this;} public String getAction(){return action;} public Intent setData(Uri u){data=u;return this;} public Uri getData(){return data;} public Class<?> getTargetClass(){return target;} public Intent putExtra(String k,String v){extras.put(k,v);return this;} public Intent putExtra(String k,boolean v){extras.put(k,v);return this;} public Intent removeExtra(String k){extras.remove(k);return this;} public String getStringExtra(String k){Object v=extras.get(k);return v instanceof String?(String)v:null;} public boolean getBooleanExtra(String k,boolean d){Object v=extras.get(k);return v instanceof Boolean?(Boolean)v:d;} }
